const fs = require('fs');
let XLSX;
try {
  XLSX = require('@e965/xlsx');
} catch (e) {
  try {
    XLSX = require('xlsx');
  } catch (err) {
    XLSX = require('C:/Users/VAGEESHA/AppData/Roaming/npm/node_modules/n8n/node_modules/@e965/xlsx');
  }
}

const dirPath = 'C:/n8n-data';
const filePath = 'C:/n8n-data/student_form_data.xlsx';
const queuePath = 'C:/n8n-data/.pending_submissions.json';

if (!fs.existsSync(dirPath)) {
  fs.mkdirSync(dirPath, { recursive: true });
}

const input = $json;
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const timestamp = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;

const newRow = {
  'Timestamp': timestamp,
  'Full Name': input['Full Name'] || input['full_name'] || input['FullName'] || '',
  'Email': input['Email'] || input['email'] || '',
  'Mobile Number': input['Mobile Number'] || input['mobile_number'] || input['MobileNumber'] || '',
  'Company Name': input['Company Name'] || input['company_name'] || input['CompanyName'] || '',
  'City': input['City'] || input['city'] || ''
};

// 1. Read existing rows from Excel if file exists
let existingData = [];
if (fs.existsSync(filePath)) {
  try {
    const wb = XLSX.readFile(filePath);
    const sheetName = wb.SheetNames[0] || 'Submissions';
    const sheet = wb.Sheets[sheetName];
    if (sheet) {
      existingData = XLSX.utils.sheet_to_json(sheet);
    }
  } catch (err) {
    // Reading error fallback
  }
}

// 2. Read any pending submissions previously queued when Excel was locked
let pendingData = [];
if (fs.existsSync(queuePath)) {
  try {
    const queueContent = fs.readFileSync(queuePath, 'utf8');
    pendingData = JSON.parse(queueContent);
    if (!Array.isArray(pendingData)) pendingData = [];
  } catch (err) {
    pendingData = [];
  }
}

// Merge all rows: existing on disk + pending queued rows + current row
const allRows = [...existingData, ...pendingData, newRow];

// 3. Try to write to Excel file
try {
  const newSheet = XLSX.utils.json_to_sheet(allRows, {
    header: ['Timestamp', 'Full Name', 'Email', 'Mobile Number', 'Company Name', 'City']
  });
  const newWb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(newWb, newSheet, 'Submissions');
  XLSX.writeFile(newWb, filePath);

  // Clear queue since all rows are written
  if (fs.existsSync(queuePath)) {
    try { fs.unlinkSync(queuePath); } catch (e) {}
  }

  return [{
    json: {
      status: 'success',
      message: 'Data successfully saved to Excel file',
      filePath: 'C:\\n8n-data\\student_form_data.xlsx',
      totalRows: allRows.length,
      submittedRecord: newRow
    }
  }];
} catch (err) {
  // If file is locked by Excel (EBUSY / EPERM), queue the unwritten submissions
  pendingData.push(newRow);
  fs.writeFileSync(queuePath, JSON.stringify(pendingData, null, 2), 'utf8');

  return [{
    json: {
      status: 'queued',
      message: 'Excel file is currently locked/opened in Microsoft Excel. Record was safely stored in queue and will auto-merge into student_form_data.xlsx as soon as Excel is closed!',
      queuedRow: newRow,
      totalPendingRows: pendingData.length
    }
  }];
}

const fs = require('fs');
