const topic = getField('Topic / Lesson Title', 'topic', 'topic_title', 'field-4');
const studentCount = parseInt(getField('Number of Students', 'studentCount', 'student_count', 'students', 'field-5') || '50', 10) || 50;
const duration = parseInt(getField('Class Duration (Minutes)', 'Class Duration', 'duration', 'field-6') || '60', 10) || 60;
