const additionalInstructions = getField('Additional Instructions / Key Themes', 'Additional Instructions', 'additionalInstructions', 'field-11') || 'Focus on intuitive clarity, practical application, and active student participation.';
const rawStudentEmails = getField('Student Email Addresses (Optional / comma-separated or leave blank for class roster)', 'Student Email Addresses', 'studentEmails', 'student_emails', 'emails', 'student_email', 'field-12');
const emailDispatchOption = getField('Email Dispatch Option', 'emailDispatchOption', 'email_dispatch', 'field-13') || 'Send Email with .md Attachment to All Students';

const missingFields = [];
if (!teacherName) missingFields.push('Teacher Name');
if (!subject) missingFields.push('Subject');
if (!topic) missingFields.push('Topic / Lesson Title');
if (!duration || duration < 15) missingFields.push('Class Duration (must be >= 15 min)');

if (missingFields.length > 0) {
  throw new Error('Input Validation Failed: Missing required fields: ' + missingFields.join(', '));
}

let studentRecipients = [];
if (rawStudentEmails && rawStudentEmails.trim() !== '') {
  const parts = rawStudentEmails.split(/[,;\n\r]+/).map(s => s.trim()).filter(Boolean);
  studentRecipients = parts.map((em, idx) => ({
    id: 'STU-' + (idx + 1),
    name: 'Student ' + (idx + 1),
    email: em,
    course: courseSemester
  }));
} else {
  const sanitize = (str) => String(str || '').replace(/[^a-zA-Z0-9_-]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '');
  const subjectFolder = sanitize(subject);
  const possibleRosterPaths = [
    path.join('c:\\Users\\VAGEESHA\\Desktop\\n8n 1\\College_Lesson_Plans', subjectFolder, 'student_roster.json'),
    path.join('c:\\Users\\VAGEESHA\\Desktop\\n8n 1\\College_Lesson_Plans', 'default_student_roster.json'),
    path.join('C:\\n8n-data\\College_Lesson_Plans', subjectFolder, 'student_roster.json'),
    path.join('C:\\n8n-data\\College_Lesson_Plans', 'default_student_roster.json')
  ];

  for (const rp of possibleRosterPaths) {
    if (fs.existsSync(rp)) {
      try {
        const rosterData = JSON.parse(fs.readFileSync(rp, 'utf8'));
        if (Array.isArray(rosterData) && rosterData.length > 0) {
          studentRecipients = rosterData;
          break;
        }
      } catch (e) {}
    }
  }
}

if (studentRecipients.length === 0) {
  studentRecipients = [
    { id: 'STU-01', name: 'Class Representative', email: 'class.representative@college.edu', course: courseSemester },
    { id: 'STU-02', name: 'Student Batch Group', email: 'students2026@college.edu', course: courseSemester }
