const fs = require('fs');
const path = require('path');

const cand = $json;
const possiblePaths = [
  path.resolve('c:/Users/VAGEESHA/Desktop/my new n8n/data/candidates.json'),
  path.resolve('c:/Users/VAGEESHA/Desktop/my n8n new/data/candidates.json'),
  path.resolve('./data/candidates.json')
];

let targetPath = possiblePaths[0];
for (const p of possiblePaths) {
  const dir = path.dirname(p);
  if (fs.existsSync(dir)) {
    targetPath = p;
    break;
  }
}

try {
  fs.mkdirSync(path.dirname(targetPath), { recursive: true });
} catch (e) {}

let candidateList = [];
if (fs.existsSync(targetPath)) {
  try {
    candidateList = JSON.parse(fs.readFileSync(targetPath, 'utf8'));
    if (!Array.isArray(candidateList)) candidateList = [];
  } catch (e) {
    candidateList = [];
  }
}

// Update existing or prepend new candidate
const existingIdx = candidateList.findIndex(c => c.id === cand.id || (c.email === cand.email && c.roleApplied === cand.roleApplied));
if (existingIdx >= 0) {
  candidateList[existingIdx] = { ...candidateList[existingIdx], ...cand };
} else {
  candidateList.unshift(cand);
}

try {
  fs.writeFileSync(targetPath, JSON.stringify(candidateList, null, 2), 'utf8');
} catch (err) {}

return [{
  json: {
    success: true,
    candidate: cand,
    totalCandidatesInDb: candidateList.length,
    persistedAt: new Date().toISOString()
  }
}];
